// src/app/utils/pdfGenerator.ts
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { RoomInput } from '../data/calculatorTypes';

// Logo oficial em Base64
const LOGO_BASE64 = 'data:image/jpeg;base64,'; 

interface PDFQuoteOptions {
  clientName: string;
  clientPhone?: string;
  rooms: RoomInput[];
  quote: {
    totalAreaM2: number;
    suggestedFinalPrice: number;
    finalAgreedPrice?: number;
    [key: string]: any;
  };
  notes?: string;
}

export function generateQuotePDF({
  clientName,
  clientPhone,
  rooms,
  quote,
}: PDFQuoteOptions) {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const today = new Date().toLocaleDateString('pt-BR');
  const validUntil = new Date(Date.now() + 15 * 24 * 60 * 60 * 1000).toLocaleDateString('pt-BR');

  // Paleta Visual
  const brandDark = [24, 24, 27] as const;      // Zinco 900
  const brandRed = [168, 30, 45] as const;      // Vinho Bordô
  const textDark = [39, 39, 42] as const;       // Zinco 800
  const textMuted = [113, 113, 122] as const;   // Zinco 500
  const bgLight = [244, 244, 245] as const;     // Zinco 100

  // 1. CABEÇALHO SUPERIOR
  doc.setFillColor(...brandDark);
  doc.rect(0, 0, 210, 32, 'F');

  doc.setFillColor(...brandRed);
  doc.rect(0, 32, 210, 2, 'F');

  if (LOGO_BASE64) {
    try {
      doc.addImage(LOGO_BASE64, 'JPEG', 14, 6, 20, 20);
    } catch {
      // Fallback sem quebrar se a string base64 for inválida
    }
  }

  const headerLeftOffset = LOGO_BASE64 ? 38 : 14;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(15);
  doc.setTextColor(255, 255, 255);
  doc.text('O PONTO DO GESSO', headerLeftOffset, 16);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(212, 212, 216);
  doc.text('Forros Tradicionais • Molduras • Sancas • Revestimento Liso', headerLeftOffset, 22);

  // Badge de Proposta Técnica
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(255, 255, 255);
  doc.text('PROPOSTA COMERCIAL', 196, 16, { align: 'right' });
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(212, 212, 216);
  doc.text(`Emissão: ${today}`, 196, 22, { align: 'right' });

  // 2. CARDS DE INFORMAÇÕES (CLIENTE E CONDIÇÕES)
  const startCardY = 40;
  
  // Card Cliente
  doc.setFillColor(...bgLight);
  doc.roundedRect(14, startCardY, 88, 22, 2, 2, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(...brandRed);
  doc.text('DADOS DO CLIENTE', 18, startCardY + 6);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...textDark);
  doc.text(clientName || 'Cliente não identificado', 18, startCardY + 12);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(...textMuted);
  doc.text(`Contato: ${clientPhone || 'Não informado'}`, 18, startCardY + 17);

  // Card Validade / Prazo
  doc.setFillColor(...bgLight);
  doc.roundedRect(108, startCardY, 88, 22, 2, 2, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(...brandRed);
  doc.text('VALIDADE & CONDIÇÕES', 112, startCardY + 6);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(...textDark);
  doc.text(`Validade da Proposta: 15 dias (até ${validUntil})`, 112, startCardY + 12);
  doc.text('Início: A combinar após aprovação', 112, startCardY + 17);

  // 3. TABELA DE ESPECIFICAÇÃO DE AMBIENTES E SERVIÇOS
  const tableRows: (string | number)[][] = [];

  rooms.forEach((room) => {
    const area = (room.lengthMeters * room.widthMeters).toFixed(2);
    const perimeter = (2 * (room.lengthMeters + room.widthMeters)).toFixed(2);

    room.services.forEach((srv, srvIndex) => {
      let serviceTitle = '';
      let executionType = 'Metragem';
      let measureUnit = `${area} m²`;

      switch (srv.type) {
        case 'FORRO_PLAQUINHA_60X60':
          serviceTitle = 'Forro Plaquinha Tradicional 60x60';
          executionType = `Dimensões: ${room.lengthMeters}m x ${room.widthMeters}m`;
          measureUnit = `${area} m²`;
          break;
        case 'REVESTIMENTO_GESSO_LISO':
          serviceTitle = 'Aplicação de Gesso Liso em Alvenaria';
          executionType = 'Parede / Superfície';
          measureUnit = `${area} m²`;
          break;
        case 'SANCA_ABERTA_GESSO':
          serviceTitle = 'Sanca Aberta com Aba e Espaço de Fita LED';
          executionType = 'Instalação Perimetral';
          measureUnit = `${srv.customLinearMeters || perimeter} m lineares`;
          break;
        case 'SANCA_FECHADA_GESSO':
          serviceTitle = 'Sanca Fechada Estruturada';
          executionType = 'Instalação Perimetral';
          measureUnit = `${srv.customLinearMeters || perimeter} m lineares`;
          break;
        case 'MOLDURA_RODATOPO':
          serviceTitle = 'Moldura de Roda-topo e Acabamento';
          executionType = 'Colagem e Arremate';
          measureUnit = `${srv.customLinearMeters || perimeter} m lineares`;
          break;
        case 'CORTINEIRO_GESSO':
          serviceTitle = 'Cortineiro Embutido';
          executionType = 'Instalação Linear';
          measureUnit = `${srv.customLinearMeters || perimeter} m lineares`;
          break;
      }

      tableRows.push([
        srvIndex === 0 ? room.name : '',
        serviceTitle,
        executionType,
        measureUnit,
      ]);
    });
  });

  autoTable(doc, {
    startY: 68,
    head: [['Ambiente', 'Serviço / Execução', 'Tipo', 'Metragem']],
    body: tableRows,
    theme: 'grid',
    headStyles: {
      fillColor: [24, 24, 27],
      textColor: [255, 255, 255],
      fontSize: 8,
      fontStyle: 'bold',
      halign: 'left',
    },
    bodyStyles: {
      fontSize: 8,
      textColor: [39, 39, 42],
    },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 42 },
      1: { cellWidth: 70 },
      2: { cellWidth: 40, textColor: [113, 113, 122] },
      3: { cellWidth: 30, halign: 'right', fontStyle: 'bold' },
    },
    margin: { left: 14, right: 14 },
    styles: {
      cellPadding: 3,
      lineColor: [228, 228, 231],
      lineWidth: 0.1,
    },
  });

  const tableEnd = (doc as any).lastAutoTable.finalY + 6;

  // 4. QUADRO DE VALOR FINAL CONSOLIDADO (Reflete valor negociado se existir)
  const finalPriceToDisplay = (quote.finalAgreedPrice !== undefined && quote.finalAgreedPrice > 0)
    ? quote.finalAgreedPrice
    : quote.suggestedFinalPrice;

  doc.setFillColor(...bgLight);
  doc.roundedRect(14, tableEnd, 182, 24, 2, 2, 'F');
  doc.setDrawColor(228, 228, 231);
  doc.roundedRect(14, tableEnd, 182, 24, 2, 2, 'D');

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(...textMuted);
  doc.text(`Área Total Estimada de Serviço: ${quote.totalAreaM2.toFixed(2)} m²`, 20, tableEnd + 8);
  doc.text('Incluso: Materiais de fixação, arames, sisal, chumbamento e mão de obra especializada.', 20, tableEnd + 15);

  const formattedPrice = finalPriceToDisplay.toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  });

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  doc.setTextColor(...brandRed);
  doc.text(`TOTAL: ${formattedPrice}`, 190, tableEnd + 13, { align: 'right' });

  // 5. CONDIÇÕES GERAIS E PAGAMENTO
  const termsY = tableEnd + 30;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...textDark);
  doc.text('CONDIÇÕES GERAIS E PAGAMENTO', 14, termsY);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textMuted);

  const terms = [
    '1. Sinal de 50% na aprovação para aquisição e separação dos insumos; 50% na entrega e aceite dos serviços.',
    '2. Métodos aceitos: PIX, Transferência e Cartão de Crédito (taxas da operadora sob consulta).',
    '3. O cliente deve garantir que o local esteja desimpedido, com fornecimento ativo de água e ponto de energia 110/220V.',
    '4. Garantia total contra descolamento ou vícios de instalação conforme normas de acabamento fino em gesso.',
  ];

  terms.forEach((term, idx) => {
    doc.text(term, 14, termsY + 5 + idx * 4.2);
  });

  // 6. LINHAS DE ASSINATURA
  const signY = termsY + 28;
  doc.setDrawColor(212, 212, 216);
  doc.setLineWidth(0.3);
  doc.line(20, signY, 85, signY);
  doc.line(125, signY, 190, signY);

  doc.setFontSize(7.5);
  doc.setTextColor(...textDark);
  doc.text('O Ponto do Gesso', 52.5, signY + 4, { align: 'center' });
  doc.text('Assinatura do Cliente', 157.5, signY + 4, { align: 'center' });

  const fileName = `Orcamento_${(clientName || 'Cliente').replace(/\s+/g, '_')}_PontoDoGesso.pdf`;
  doc.save(fileName);
}